/* Golden Braid / AIDM / S22 Gnomes — labelled Combat and Encounter test cases
FILE: MonsterTestCase_Mentzer_Basic_Gnome_Insert.sql
TARGET: PEQUOD / DnD (Test.MonsterTestCase)
Mentzer Basic 1983 Gnome and Kobold monster entries, printed pp.30,32;
Player Manual crossbow and war-hammer mechanics.
Contains 18 COMBAT and 10 ENCOUNTER definitions, strictly separated.
Alternate leader/guard/chieftain profiles are in their own cases, not in
the two-Gnome baseline; no Encounter engine acceptance is claimed.
Idempotent INSERT ONLY, specified not approved/executed. 2026-11-22.
*/
USE [DnD];
GO
IF OBJECT_ID(N'Test.MonsterTestCase',N'U') IS NULL THROW 57323,N'Test.MonsterTestCase missing',1;
IF NOT EXISTS(SELECT 1 FROM [Test].[MonsterTestScenario] WHERE [ScenarioCode]=N'GNOME-T001')
 THROW 57324,N'GNOME-T001 missing: deploy scenario first',1;
GO
SET XACT_ABORT ON;
GO
BEGIN TRY
 BEGIN TRAN;
 DECLARE @Seed TABLE ([ScenarioCode] NVARCHAR(MAX) NOT NULL,[TestCaseCode] NVARCHAR(MAX) NOT NULL,[SequenceNo] INT NOT NULL,[TestName] NVARCHAR(MAX) NOT NULL,[TestPhase] NVARCHAR(MAX) NOT NULL,[TestStatus] NVARCHAR(MAX) NOT NULL,[TestRevision] INT NOT NULL,[GivenText] NVARCHAR(MAX) NOT NULL,[ExpectedText] NVARCHAR(MAX) NOT NULL,[DiceFixtureJson] NVARCHAR(MAX) NULL,[AdditionalDataJson] NVARCHAR(MAX) NULL,[LinkedStoryRef] NVARCHAR(MAX) NULL,[AutomatedTestRef] NVARCHAR(MAX) NULL,[Notes] NVARCHAR(MAX) NULL);
 INSERT INTO @Seed ([ScenarioCode],[TestCaseCode],[SequenceNo],[TestName],[TestPhase],[TestStatus],[TestRevision],[GivenText],[ExpectedText],[DiceFixtureJson],[AdditionalDataJson],[LinkedStoryRef],[AutomatedTestRef],[Notes]) VALUES
 (N'GNOME-T001',N'GNM-C01',1,N'Ordinary Gnome 1-HD attack and AC 5',N'COMBAT',N'Specified',1,N'GNM-T001-1 attacks using its equipped crossbow; defender AC and attack roll supplied by authoritative Combat fixture.',N'Resolve exactly one ordinary 1-HD monster attack against validated target AC. Gnome AC 5 is its DEFENSE, not an attack bonus.',N'{"attack_d20":15}',N'{"attack_as":"1 HD monster","gnome_armor_class":5,"attacks_per_round":1}',N'AIDM-DES-001.7',NULL,N'Specified Combat engine case; not executed.'),
 (N'GNOME-T001',N'GNM-C02',2,N'War hammer damage with approved mode',N'COMBAT',N'Specified',1,N'GNM-T001-2 hits a valid adjacent target with its equipped war hammer; variable weapon damage enabled.',N'Roll exactly 1d6 for war hammer; d6=4 deals 4 HP. No extra Gnome hit or damage effect.',N'{"attack_d20":19,"war_hammer_d6":4}',N'{"expected_damage":4,"weapon":"war_hammer"}',N'AIDM-DES-001.7',NULL,N'Specified Combat engine case; not executed.'),
 (N'GNOME-T001',N'GNM-C03',3,N'Crossbow quarrel normal damage',N'COMBAT',N'Specified',1,N'GNM-T001-1 scores a legal ranged hit; validated crossbow quarrel damage is 1d6 in both supported weapon damage modes.',N'Damage d6=5 deals 5 HP; do not add a Gnome racial bonus or invent a special crossbow damage die.',N'{"attack_d20":19,"quarrel_d6":5}',N'{"expected_damage":5,"weapon":"crossbow"}',N'AIDM-DES-001.7',NULL,N'Specified Combat engine case; not executed.'),
 (N'GNOME-T001',N'GNM-C04',4,N'Crossbow short medium long and out-of-range',N'COMBAT',N'Specified',1,N'One Gnome with a light crossbow attacks otherwise valid targets at 30,90,150,181 feet on independent branches; no cover or other modifiers.',N'Using Mentzer crossbow bands 60/120/180 ft, apply +1/0/-1 to hit at 30/90/150 ft. Reject 181-ft shot as out of range, no damage or legal attack.',N'{"distance_feet":[30,90,150,181]}',N'{"range_feet":{"short":60,"medium":120,"long":180},"expected_hit_modifier":[1,0,-1,null],"attack_allowed":[true,true,true,false]}',N'AIDM-DES-001.7',NULL,N'Specified Combat engine case; not executed.'),
 (N'GNOME-T001',N'GNM-C05',5,N'Cover changes ranged hit roll only',N'COMBAT',N'Specified',1,N'A valid crossbow shot meets source-supported partial cover adjudicated as -2 to hit by DM.',N'Apply -2 to hit (in addition to applicable range), never to damage or target AC; do not let narration fabricate cover.',NULL,N'{"verified_cover_penalty":-2,"damage_modifier_from_cover":0}',N'AIDM-DES-001.7',NULL,N'Specified Combat engine case; not executed.'),
 (N'GNOME-T001',N'GNM-C06',6,N'Two-handed crossbow restrictions',N'COMBAT',N'Specified',1,N'GNM-T001-1 shoots an equipped light crossbow while Mentzer two-handed weapon rule is active.',N'Resolve the established two-handed restriction (cannot use a shield and loses initiative); do not invent a Gnome-specific crossbow exception. Apply only as supported by enabled rules.',N'{"party_initiative_d6":5,"gnome_side_initiative_d6":6}',N'{"two_handed":true,"shield_allowed_while_using":false,"weapon_initiative_restriction":"always loses initiative under Mentzer two-handed rules"}',N'AIDM-DES-001.7',NULL,N'Specified Combat engine case; not executed.'),
 (N'GNOME-T001',N'GNM-C07',7,N'War hammer to crossbow interpretation and equipment',N'COMBAT',N'Specified',1,N'One ordinary Gnome has BOTH weapons explicitly equipped in an alternate branch and is using war hammer; on the next lawful declared action changes to crossbow.',N'Resolve weapon switch only if allowed by shared action/equipment rules, then apply crossbow range and two-handed restrictions. Do not require fresh unprompted intent every round or invent a swap bonus.',NULL,N'{"weapons":["war_hammer","crossbow"],"selection_after":"crossbow","action_timing":"normal canonical combat action"}',N'AIDM-DES-001.7',NULL,N'Specified Combat engine case; not executed.'),
 (N'GNOME-T001',N'GNM-C08',8,N'Base morale 8 succeeds at 8',N'COMBAT',N'Specified',1,N'GNOME-T001 has no leader or chieftain; one source-prescribed morale checkpoint occurs and 2d6=8.',N'Apply Morale 8: result 8 passes; retain fight under normal morale procedure. No second check.',N'{"morale_2d6":[4,4]}',N'{"morale_used":8,"check_passes":true,"extra_check":false}',N'AIDM-DES-001.7',NULL,N'Specified Combat engine case; not executed.'),
 (N'GNOME-T001',N'GNM-C09',9,N'Base morale 8 fails at 9',N'COMBAT',N'Specified',1,N'GNOME-T001 has no leader or chieftain; one prescribed morale checkpoint occurs and 2d6=9.',N'Apply Morale 8: result 9 fails. Deterministic result is returned for lawful withdrawal/surrender action resolution; no invented reroll.',N'{"morale_2d6":[4,5]}',N'{"morale_used":8,"check_passes":false}',N'AIDM-DES-001.7',NULL,N'Specified Combat engine case; not executed.'),
 (N'GNOME-T001',N'GNM-C10',10,N'Living visible leader raises morale to 10',N'COMBAT',N'Specified',1,N'Alternate fixture has an ordinary Gnome with LOS to a living leader when a normal morale checkpoint occurs; dice=9.',N'Use Morale 10, so 9 passes; sight and alive are both required. Do not grant it solely for belonging to the same clan.',N'{"morale_2d6":[4,5]}',N'{"leader_alive":true,"leader_visible":true,"morale_used":10,"check_passes":true}',N'AIDM-DES-001.7',NULL,N'Specified Combat engine case; not executed.'),
 (N'GNOME-T001',N'GNM-C11',11,N'Leader death removes morale benefit',N'COMBAT',N'Specified',1,N'Alternate combat state: leader previously visible is dead when a normally scheduled morale check is due; ordinary Gnome rolls 9.',N'Use Morale 8 and fail on 9; no extra morale check triggered only by changing visibility or survival status.',N'{"morale_2d6":[4,5]}',N'{"leader_alive":false,"leader_visible":false,"morale_used":8,"check_passes":false,"extra_check_on_aura_loss":false}',N'AIDM-DES-001.7',NULL,N'Specified Combat engine case; not executed.'),
 (N'GNOME-T001',N'GNM-C12',12,N'Living leader outside sight gives base morale',N'COMBAT',N'Specified',1,N'Alternate state has a living 11-HP leader behind an opaque wall; Gnome cannot see them; normal morale dice=9.',N'Morale remains 8, and 9 fails. Do not use line-of-sight from fictional art or narration to infer visibility.',N'{"morale_2d6":[4,5]}',N'{"leader_alive":true,"leader_visible":false,"morale_used":8,"check_passes":false}',N'AIDM-DES-001.7',NULL,N'Specified Combat engine case; not executed.'),
 (N'GNOME-T001',N'GNM-C13',13,N'Ordinary leader fixed HP and 2-HD attack row',N'COMBAT',N'Specified',1,N'Alternate group includes a Gnome leader, fixed 11 HP, who makes one legal equipped-weapon attack.',N'Keep exactly 11 HP; use 2-HD monster hit row, not ordinary 1-HD and do not roll 2d8 for HP. No innate leader damage bonus.',N'{"attack_d20":15}',N'{"role":"leader","fixed_hp":11,"attack_as_hd":2,"additional_damage_bonus":0}',N'AIDM-DES-001.7',NULL,N'Specified Combat engine case; not executed.'),
 (N'GNOME-T001',N'GNM-C14',14,N'Bodyguard 10-13 HP attacks as 3 HD',N'COMBAT',N'Specified',1,N'Alternate chieftain-lair combat branch includes bodyguards fixed at 10,11,12 and 13 HP.',N'Each distinct bodyguard attacks on 3-HD monster row using its actual equipped weapon, with its fixed encounter-assigned 10-13 HP; do not roll 3d8 or invent a protective-intercept reaction.',N'{"bodyguard_hp":[10,11,12,13]}',N'{"role":"bodyguard","attack_as_hd":3,"valid_hp_range":[10,13],"invented_guard_reaction":false}',N'AIDM-DES-001.7',NULL,N'Specified Combat engine case; not executed.'),
 (N'GNOME-T001',N'GNM-C15',15,N'Clan chieftain 18 HP 4-HD hit and +1 damage',N'COMBAT',N'Specified',1,N'Alternate lair branch has an 18-HP chieftain hitting once with a war hammer and rolling weapon damage 5.',N'Use 4-HD hit row and 18 fixed HP; add exactly +1 to damage for 6 final damage. Do NOT add +1 to hit or grant extra attack.',N'{"attack_d20":18,"weapon_damage_d6":5}',N'{"role":"chieftain","fixed_hp":18,"attack_as_hd":4,"source_damage_bonus":1,"final_damage":6,"hit_bonus_from_role":0}',N'AIDM-DES-001.7',NULL,N'Specified Combat engine case; not executed.'),
 (N'GNOME-T001',N'GNM-C16',16,N'Save As Dwarf 1 is only saving throw profile',N'COMBAT',N'Specified',1,N'One ordinary Gnome attempts a source-prescribed saving throw in combat; no separate Dwarf-class NPC features are assigned.',N'Use Dwarf level 1 saving throw row; do not grant Dwarf class abilities, class THAC0, damage or other unsupported bonuses.',NULL,N'{"save_as":"Dwarf 1","dwarf_class_abilities":false}',N'AIDM-DES-001.7',NULL,N'Specified Combat engine case; not executed.'),
 (N'GNOME-T001',N'GNM-C17',17,N'Movement and infravision do not grant attack bonus',N'COMBAT',N'Specified',1,N'GNM-T001-2 moves under legal combat conditions; its Gnome species has movement 20 ft per round and 90-ft infravision.',N'Apply normal 20-ft/round movement and known visibility; infravision affects what can be seen, NOT an automatic hit, damage, AC, initiative, or surprise modifier.',NULL,N'{"movement_round_feet":20,"movement_turn_feet":60,"infravision_feet":90,"gnome_vision_hit_bonus":0}',N'AIDM-DES-001.7',NULL,N'Specified Combat engine case; not executed.'),
 (N'GNOME-T001',N'GNM-C18',18,N'Kobold rivalry never changes attack algorithm',N'COMBAT',N'Specified',1,N'Combat handoff already contains a Gnome opponent and a Kobold opponent; any hostility was resolved by Encounter.',N'Run normal attacks, damage, initiative, morale and conditions. No +1 against Kobolds, bonus action, automatic hit, or encounter reaction logic within Combat.',NULL,N'{"gnome_vs_kobold_hit_bonus":0,"automatic_targeting":false,"encounter_disposition_in_combat":false}',N'AIDM-DES-001.7',NULL,N'Specified Combat engine case; not executed.'),
 (N'GNOME-T001',N'GNM-E01',19,N'Two ordinary Gnomes in synthetic fixture',N'ENCOUNTER',N'Specified',1,N'Synthetic Miners Watch is selected with two ordinary 1-HD Gnomes and reproducible individual HP rolls 7 and 5.',N'Build two separate actors with AC5 and 7/5 HP, total 12; assign light crossbow to first, war hammer to second, with no leader or bodyguard.',N'{"hp_1d8":[7,5]}',N'{"count":2,"starting_hp":[7,5],"total_hp":12,"leaders":0,"bodyguards":0,"chieftains":0}',NULL,NULL,N'Future Encounter Engine specification; not implemented or executed.'),
 (N'GNOME-T001',N'GNM-E02',20,N'Scene allows communication and refusal to fight',N'ENCOUNTER',N'Specified',1,N'Party meets two Gnomes at the worked stone gallery while Kobolds are absent.',N'Describe only known surroundings, visible gear and Gnome behaviour; allow dialogue, trade, avoidance or aggression according to circumstance and player intent. Do not force fighting or reveal motives.',NULL,N'{"forced_combat":false,"dialogue_possible":true,"avoidance_possible":true}',NULL,NULL,N'Future Encounter Engine specification; not implemented or executed.'),
 (N'GNOME-T001',N'GNM-E03',21,N'Gnomes usually attack Kobolds on sight',N'ENCOUNTER',N'Specified',1,N'In a variant meeting, two Gnomes visually recognise an approaching Kobold.',N'Apply Mentzer usually-attack-on-sight guidance to encounter disposition; do not change the probabilistic wording to ALWAYS, invent a die threshold or give combat bonuses.',NULL,N'{"rivalry":"Gnomes usually attack Kobolds on sight","always":false,"engine":"ENCOUNTER"}',NULL,NULL,N'Future Encounter Engine specification; not implemented or executed.'),
 (N'GNOME-T001',N'GNM-E04',22,N'Kobolds will attack Gnomes on sight',N'ENCOUNTER',N'Specified',1,N'In a second variant meeting, Kobolds recognise Gnomes.',N'Treat Kobold-to-Gnome hostile intent as WILL attack on sight per Kobold entry, subject to actual perception and circumstances; no new hit/damage modifier.',NULL,N'{"rivalry":"Kobolds WILL attack Gnomes on sight","engine":"ENCOUNTER","combat_modifier":0}',NULL,NULL,N'Future Encounter Engine specification; not implemented or executed.'),
 (N'GNOME-T001',N'GNM-E05',23,N'Leader allocation at a group of 20 Gnomes',N'ENCOUNTER',N'Specified',1,N'A separate, larger group fixture has twenty Gnomes, not the two-Gnome baseline.',N'Represent one designated leader with fixed 11 HP attacking as 2-HD; normal members remain ordinary 1-HD. Do not create leader in GNOME-T001.',NULL,N'{"normal_group_size":20,"leader_count":1,"leader_fixed_hp":11,"leader_attack_as_hd":2,"baseline_leader_count":0}',NULL,NULL,N'Future Encounter Engine specification; not implemented or executed.'),
 (N'GNOME-T001',N'GNM-E06',24,N'Lair chieftain plus 1-6 bodyguards',N'ENCOUNTER',N'Specified',1,N'Alternate true Gnome lair fixture includes its clan chieftain and bodyguard count die=4.',N'Create ONE chieftain fixed 18 HP attacking as 4-HD with +1 weapon damage and FOUR bodyguards with valid individually assigned HP 10,11,12,13 attacking as 3-HD; no global requirement to have chieftain in every random encounter.',N'{"bodyguard_count_d6":4,"bodyguard_fixed_hp":[10,11,12,13]}',N'{"chieftain_count":1,"chieftain_hp":18,"chieftain_attack_as_hd":4,"chieftain_damage_bonus":1,"bodyguard_count":4,"bodyguard_attack_as_hd":3}',NULL,NULL,N'Future Encounter Engine specification; not implemented or executed.'),
 (N'GNOME-T001',N'GNM-E07',25,N'Normal surprise evaluated once per side',N'ENCOUNTER',N'Specified',1,N'When two ordinary Gnomes meet adventurers, example surprise dice party=5 and Gnomes=4.',N'Neither side surprised under normal one-d6-per-side procedure; crossbow or infravision gives no unearned automatic surprise.',N'{"party_surprise_d6":5,"gnome_surprise_d6":4}',N'{"one_roll_per_side":true,"party_surprised":false,"gnomes_surprised":false}',NULL,NULL,N'Future Encounter Engine specification; not implemented or executed.'),
 (N'GNOME-T001',N'GNM-E08',26,N'Infravision requires actual sightline and conditions',N'ENCOUNTER',N'Specified',1,N'A Gnome may observe a target 80 ft away in suitable darkness, while another target is 95 ft away.',N'Use 90-ft infravision limit plus actual line-of-sight/obstructions; do not automatically identify all creatures, presume surprise, or use generated art as geometry.',NULL,N'{"infravision_feet":90,"within_range_feet":80,"outside_range_feet":95,"automatic_reveal":false}',NULL,NULL,N'Future Encounter Engine specification; not implemented or executed.'),
 (N'GNOME-T001',N'GNM-E09',27,N'Disposition toward non-Kobolds not preset hostile',N'ENCOUNTER',N'Specified',1,N'Characters meet ordinary Lawful or Neutral Gnomes without Kobolds in the party.',N'Run actual reaction/context/dialogue; war with Kobolds does not mean hostile to all PCs, and desire for gems is not forced robbery.',NULL,N'{"automatic_player_hostility":false,"gnome_alignment":["Lawful","Neutral"],"reaction_context_required":true}',NULL,NULL,N'Future Encounter Engine specification; not implemented or executed.'),
 (N'GNOME-T001',N'GNM-E10',28,N'Structured handoff keeps combat purely algorithmic',N'ENCOUNTER',N'Specified',1,N'The two-Gnome fixture escalates to actual combat after Encounter has resolved approach, perception, and any surprise.',N'Hand off GNM-T001-1/2 HP7/5, AC5, attack as 1 HD, crossbow/warhammer, morale8, 20-ft/round, validated positions, effects and surprise. Do not hand off social bluffing or NPC dialogue as combat modifiers.',NULL,N'{"actors":["GNM-T001-1","GNM-T001-2"],"starting_hp":[7,5],"armor_class":5,"morale":8,"encounter_logic_in_combat":false,"leader_present":false}',NULL,NULL,N'Future Encounter Engine specification; not implemented or executed.');
 INSERT INTO [Test].[MonsterTestCase] ([ScenarioCode],[TestCaseCode],[SequenceNo],[TestName],[TestPhase],[TestStatus],[TestRevision],[GivenText],[ExpectedText],[DiceFixtureJson],[AdditionalDataJson],[LinkedStoryRef],[AutomatedTestRef],[Notes])
 SELECT s.[ScenarioCode],s.[TestCaseCode],s.[SequenceNo],s.[TestName],s.[TestPhase],s.[TestStatus],s.[TestRevision],s.[GivenText],s.[ExpectedText],s.[DiceFixtureJson],s.[AdditionalDataJson],s.[LinkedStoryRef],s.[AutomatedTestRef],s.[Notes] FROM @Seed AS s
 WHERE NOT EXISTS (SELECT 1 FROM [Test].[MonsterTestCase] AS t WITH(UPDLOCK,HOLDLOCK)
 WHERE t.[ScenarioCode]=s.[ScenarioCode] AND t.[TestCaseCode]=s.[TestCaseCode]);
 PRINT CONCAT(N'Inserted Gnome test definitions: ',@@ROWCOUNT);
 COMMIT;
END TRY
BEGIN CATCH
 IF @@TRANCOUNT>0 ROLLBACK;
 THROW;
END CATCH;
GO
SELECT [ScenarioCode],[TestPhase],[TestStatus],COUNT(*) AS [TestCount]
FROM [Test].[MonsterTestCase]
WHERE [ScenarioCode]=N'GNOME-T001'
GROUP BY [ScenarioCode],[TestPhase],[TestStatus]
ORDER BY [TestPhase],[TestStatus];
